package fable.hideseek.imba.client;
import fable.hideseek.imba.config.MessageSettingsConfig;import fable.hideseek.imba.net.MessageSettingsNetworking;import net.fabricmc.fabric.api.client.networking.v1.ClientPlayNetworking;import net.fabricmc.fabric.api.networking.v1.PacketByteBufs;import net.minecraft.client.gui.DrawContext;import net.minecraft.client.gui.screen.Screen;import net.minecraft.client.gui.widget.ButtonWidget;import net.minecraft.client.gui.widget.TextFieldWidget;import net.minecraft.network.PacketByteBuf;import net.minecraft.text.Text;import net.minecraft.util.math.MathHelper;import java.util.ArrayList;import java.util.List;import java.util.Locale;
public final class MessageSettingsScreen extends Screen{private static final int ROW_HEIGHT=27;private final List<MessageSettingsConfig.Entry> filtered=new ArrayList<>();private TextFieldWidget search;private int scroll;public MessageSettingsScreen(){super(Text.literal("Сообщения IMBA"));}@Override protected void init(){int w=Math.min(650,width-24),left=(width-w)/2;search=new TextFieldWidget(textRenderer,left+12,42,w-24,20,Text.empty());search.setPlaceholder(Text.literal("Поиск сообщения..."));search.setChangedListener(v->{scroll=0;rebuild();});addDrawableChild(search);addDrawableChild(ButtonWidget.builder(Text.literal("Закрыть"),b->close()).dimensions(width/2-60,height-29,120,20).build());rebuild();ClientPlayNetworking.send(MessageSettingsNetworking.REQUEST,PacketByteBufs.empty());}public void applyServerState(){rebuild();}private void rebuild(){String q=search==null?"":search.getText().trim().toLowerCase(Locale.ROOT);filtered.clear();for(var entry:MessageSettingsConfig.CATALOG)if(q.isEmpty()||entry.key().toLowerCase(Locale.ROOT).contains(q)||entry.title().toLowerCase(Locale.ROOT).contains(q))filtered.add(entry);clamp();}private int top(){return 70;}private int bottom(){return height-40;}private int rows(){return Math.max(1,(bottom()-top())/ROW_HEIGHT);}private void clamp(){scroll=MathHelper.clamp(scroll,0,Math.max(0,filtered.size()-rows()));}@Override public void render(DrawContext c,int mx,int my,float d){renderBackground(c);int w=Math.min(650,width-24),left=(width-w)/2,right=left+w;c.fill(left,8,right,height-36,0xDD181818);c.drawCenteredTextWithShadow(textRenderer,title,width/2,16,0xFFFFFFFF);c.drawCenteredTextWithShadow(textRenderer,"Зелёное = сообщение показывается • Красное = полностью скрыто",width/2,29,0xFFAAAAAA);clamp();int y=top();var state=MessageSettingsClientData.snapshot();for(int row=0;row<rows();row++){int index=scroll+row;if(index>=filtered.size())break;var entry=filtered.get(index);boolean enabled=state.getOrDefault(entry.key(),entry.defaultEnabled());c.fill(left+12,y,right-12,y+23,(index&1)==0?0x55303030:0x55404040);c.drawTextWithShadow(textRenderer,entry.title(),left+18,y+3,0xFFFFFFFF);c.drawTextWithShadow(textRenderer,entry.key(),left+18,y+13,0xFF777777);int bx=right-122;c.fill(bx,y+3,right-17,y+20,enabled?0xAA1E6B2D:0xAA5A2020);c.drawCenteredTextWithShadow(textRenderer,enabled?"ПОКАЗЫВАТЬ":"СКРЫТЬ",bx+52,y+7,enabled?0xFFAAFFAA:0xFFFFAAAA);y+=ROW_HEIGHT;}super.render(c,mx,my,d);}@Override public boolean mouseClicked(double mx,double my,int button){if(super.mouseClicked(mx,my,button))return true;if(button!=0)return false;int w=Math.min(650,width-24),left=(width-w)/2,right=left+w;if(mx<left+12||mx>=right-12||my<top()||my>=bottom())return false;int index=scroll+(int)((my-top())/ROW_HEIGHT);if(index<0||index>=filtered.size())return false;var entry=filtered.get(index);boolean enabled=!MessageSettingsClientData.isEnabled(entry.key());PacketByteBuf buf=PacketByteBufs.create();buf.writeString(entry.key(),128);buf.writeBoolean(enabled);ClientPlayNetworking.send(MessageSettingsNetworking.SET,buf);return true;}@Override public boolean mouseScrolled(double mx,double my,double amount){if(amount!=0){scroll-=(int)Math.signum(amount)*3;clamp();return true;}return super.mouseScrolled(mx,my,amount);}@Override public boolean shouldPause(){return false;}}
